all_filter_calls.call:
filter(children, i => {
        switch (i.kind) {
            case SyntaxKind.JsxExpression:
                return !!i.expression;
            case SyntaxKind.JsxText:
                return !i.containsOnlyTriviaWhiteSpaces;
            default:
                return true;
        }
    })

filter(indexInfo.components, e => {
                            // skip late bound props that contribute to the index signature - they'll be created by property creation anyway
                            return !hasLateBindableName(e);
                        })

filter(node.properties, (p): p is PropertyAssignment | ShorthandPropertyAssignment => {
                            if (!p.symbol) {
                                return false;
                            }
                            if (p.kind === SyntaxKind.PropertyAssignment) {
                                return isPossiblyDiscriminantValue(p.initializer) && isDiscriminantProperty(contextualType, p.symbol.escapedName);
                            }
                            if (p.kind === SyntaxKind.ShorthandPropertyAssignment) {
                                return isDiscriminantProperty(contextualType, p.symbol.escapedName);
                            }
                            return false;
                        })

filter(getPropertiesOfType(contextualType), s => {
                            if (!(s.flags & SymbolFlags.Optional) || !node?.symbol?.members) {
                                return false;
                            }
                            const element = node.parent.parent;
                            if (s.escapedName === jsxChildrenPropertyName && isJsxElement(element) && getSemanticJsxChildren(element.children).length) {
                                return false;
                            }
                            return !node.symbol.members.has(s.escapedName) && isDiscriminantProperty(contextualType, s.escapedName);
                        })

filter(info.components, e => {
                                    // skip late bound props that contribute to the index signature - they'll be preserved via other means
                                    return !hasLateBindableName(e);
                                })

filter(
            map(nodes, clause =>
                factory.updateHeritageClause(
                    clause,
                    visitNodes(
                        factory.createNodeArray(filter(clause.types, t => {
                            return isEntityNameExpression(t.expression) || (clause.token === SyntaxKind.ExtendsKeyword && t.expression.kind === SyntaxKind.NullKeyword);
                        })),
                        visitDeclarationSubtree,
                        isExpressionWithTypeArguments,
                    ),
                )),
            clause => clause.types && !!clause.types.length,
        )

filter(clause.types, t => {
                            return isEntityNameExpression(t.expression) || (clause.token === SyntaxKind.ExtendsKeyword && t.expression.kind === SyntaxKind.NullKeyword);
                        })

filter(exportClause.elements, element => {
        return element === originExportSpecifier || findDiagnosticForNode(element, diagnostics)?.code === errorCodes[0];
    })
